package com.gpcbellary.cms.controller; import com.gpcbellary.cms.model.Admission; import com.gpcbellary.cms.repository.AdmissionRepository; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admissions") @CrossOrigin public class AdmissionController{private final AdmissionRepository repo; public AdmissionController(AdmissionRepository repo){this.repo=repo;} @GetMapping public List<Admission> all(){return repo.findAll();} @GetMapping("/status/{status}") public List<Admission> byStatus(@PathVariable String status){return repo.findByStatusIgnoreCaseOrderByApplicationDateDesc(status);} @PostMapping public Admission create(@RequestBody Admission x){return repo.save(x);} @PutMapping("/{id}") public Admission update(@PathVariable Long id,@RequestBody Admission x){x.setId(id);return repo.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);}}
